import{c as a,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"IterateNBatch","description":"","frontmatter":{},"headers":[{"level":1,"title":"IterateNBatch","slug":"iteratenbatch"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateNBatch.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateNBatch.md"}'),l={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateNBatch.md"};function r(i,t,d,p,o,c){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="iteratenbatch" tabindex="-1">IterateNBatch <a class="header-anchor" href="#iteratenbatch" aria-label="Permalink to &quot;IterateNBatch&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>调用一次IterateNBatch，会进行N次IterateBatch计算，计算出N个多Batch的singleCoreM * singleCoreN大小的C矩阵。在调用该接口前，需将MatmulConfig中的<a href="./MatmulConfig.html#p1960754911593">isNBatch</a>参数设为true，使能多Batch输入多Batch输出功能，并调用<a href="./SetWorkspace.html">SetWorkspace</a>接口申请临时空间，用于缓存计算结果，即IterateNBatch的结果输出至<a href="./SetWorkspace.html">SetWorkspace</a>指定的Global Memory内存中。</p><p>对于BSNGD、SBNGD、BNGS1S2的Layout格式，调用该接口之前需要在tiling中使用SetALayout/SetBLayout/SetCLayout/SetBatchNum设置A/B/C的Layout轴信息和最大BatchNum数；对于Normal数据格式则需使用<a href="./../Matmul-Tiling侧接口/Matmul-Tiling类/SetBatchInfoForNormal.html">SetBatchInfoForNormal</a>设置A/B/C的M/N/K轴信息和A/B矩阵的BatchNum数。实例化Matmul时，通过MatmulType设置Layout类型，当前支持3种Layout类型：BSNGD、SBNGD、BNGS1S2。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true, bool waitIterateBatch = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void IterateNBatch(const uint32_t batchLoop, uint32_t batchA, uint32_t batchB, bool enSequentialWrite, const uint32_t matrixStrideA = 0, const uint32_t matrixStrideB = 0, const uint32_t matrixStrideC = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>获取C矩阵过程分为同步和异步两种模式： 同步：需要同步等待IterateNBatch执行结束，后续由开发者自行获取输出到Global Memory上的计算结果。异步：不需要同步等待IterateNBatch执行结束。 通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false。默认为同步模式。</td></tr><tr><td>waitIterateBatch</td><td>是否需要通过WaitIterateBatch接口等待IterateNBatch执行结束，仅在异步场景下使用。默认为false。 true：需要通过WaitIterateBatch接口等待IterateNBatch执行结束，然后由开发者自行获取输出到Global Memory上的计算结果。 false：不需要通过WaitIterateBatch接口等待IterateNBatch执行结束。调用本接口后，需要调用GetBatchTensorC接口获取C矩阵，或者由开发者自行处理等待IterateNBatch执行结束的过程。</td></tr></tbody></table><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>batchLoop</td><td>输入</td><td>当前计算的BMM个数。</td></tr><tr><td>batchA</td><td>输入</td><td>当前单次BMM调用计算左矩阵的batch数。</td></tr><tr><td>batchB</td><td>输入</td><td>当前单次BMM调用计算右矩阵的batch数，brc场景batchA/B不相同。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>输出是否连续存放数据。</td></tr><tr><td>matrixStrideA</td><td>输入</td><td>A矩阵源操作数相邻nd矩阵起始地址间的偏移，默认值是0。</td></tr><tr><td>matrixStrideB</td><td>输入</td><td>B矩阵源操作数相邻nd矩阵起始地址间的偏移，默认值是0。</td></tr><tr><td>matrixStrideC</td><td>输入</td><td>该参数预留，保持默认值0即可。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>单BMM内计算遵循之前的约束条件。</li><li>对于BSNGD、SBNGD、BNGS1S2 Layout格式，输入A、B矩阵多Batch数据总和应小于L1 Buffer的大小。</li><li>当使能MixDualMaster（双主模式）场景时，即模板参数<a href="./MatmulConfig.html#p9218181073719">enableMixDualMaster</a>设置为true，不支持使用该接口。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>实例功能：完成aGM、bGM矩阵乘，结果保存到cGm上，其中aGM数据的layout格式为BSNGD，bGM数据的layout格式为BSNGD，cGM的layout格式为BNGS1S2，左矩阵每次计算batchA个SD数据，右矩阵每次计算batchB个SD数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 创建Matmul实例</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm1;</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>g_cubeTPipePtr = &amp;pipe;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);</span></span>
<span class="line"><span>mm1.Init(&amp;tiling);</span></span>
<span class="line"><span>int g_lay = tiling.ALayoutInfoG &gt; tiling.BLayoutInfoG ? tiling.ALayoutInfoG : tiling.BLayoutInfoG;</span></span>
<span class="line"><span>int for_extent = tiling.ALayoutInfoB * tiling.ALayoutInfoN * g_lay / tiling.BatchNum;</span></span>
<span class="line"><span>mm1.SetTensorA(gm_a[0], isTransposeAIn);</span></span>
<span class="line"><span>mm1.SetTensorB(gm_b[0], isTransposeBIn);</span></span>
<span class="line"><span>mm1.SetWorkspace(workspaceGM, 0);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm1.SetBias(gm_bias[0]);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 多batch Matmul计算</span></span>
<span class="line"><span>mm1.IterateNBatch(for_extent, batchA, batchB, false);</span></span></code></pre></div>`,19)])])}const m=a(l,[["render",r]]);export{u as __pageData,m as default};
